Here is a complete, idiomatic Terraform implementation aligned with your canonical scenario. The structure uses a reusable submodule pattern, environment-specific `tfvars`, and native AWS secret management to satisfy all acceptance criteria.

### 📁 Directory Structure
```
├── versions.tf
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam_role/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

### 📦 Root Module

**`versions.tf`**
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}
```

**`main.tf`**
```hcl
module "s3" {
  source = "./modules/s3"

  bucket_name          = var.s3_bucket_name
  environment          = var.environment
  enable_replication   = var.s3_enable_replication
  replication_role_arn = var.s3_replication_role_arn
  destination_bucket_arn = var.s3_destination_bucket_arn
  common_tags          = var.common_tags
}

module "rds" {
  source = "./modules/rds"

  environment            = var.environment
  identifier             = var.rds_identifier
  instance_class         = var.rds_instance_class
  multi_az               = var.rds_multi_az
  storage_encrypted      = var.rds_storage_encrypted
  deletion_protection    = var.rds_deletion_protection
  backup_retention_period = var.rds_backup_retention
  db_name                = var.rds_db_name
  master_username        = var.rds_master_username
  vpc_subnet_ids         = var.vpc_subnet_ids
  vpc_security_group_ids = var.vpc_security_group_ids
  common_tags            = var.common_tags
}

module "iam_role" {
  source = "./modules/iam_role"

  role_name          = var.iam_role_name
  assume_role_policy = var.iam_assume_role_policy
  policy_arns        = var.iam_policy_arns
  inline_policy      = var.iam_inline_policy
  common_tags        = var.common_tags
}
```

**`variables.tf`**
```hcl
variable "environment" {
  type        = string
  description = "Target environment (dev/prod)"
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region for resource deployment"
}

variable "vpc_subnet_ids" {
  type        = list(string)
  description = "Private subnet IDs for RDS placement"
}

variable "vpc_security_group_ids" {
  type        = list(string)
  description = "Security group IDs allowing app-to-RDS traffic"
}

variable "common_tags" {
  type        = map(string)
  default     = {}
  description = "Tags applied to all resources"
}

# S3 Variables
variable "s3_bucket_name" { type = string }
variable "s3_enable_replication" { type = bool; default = false }
variable "s3_replication_role_arn" { type = string; default = "" }
variable "s3_destination_bucket_arn" { type = string; default = "" }

# RDS Variables
variable "rds_identifier" { type = string }
variable "rds_instance_class" { type = string }
variable "rds_multi_az" { type = bool; default = false }
variable "rds_storage_encrypted" { type = bool; default = true }
variable "rds_deletion_protection" { type = bool; default = true }
variable "rds_backup_retention" { type = number; default = 7 }
variable "rds_db_name" { type = string; default = "app" }
variable "rds_master_username" { type = string; default = "admin" }

# IAM Variables
variable "iam_role_name" { type = string }
variable "iam_assume_role_policy" { type = string }
variable "iam_policy_arns" { type = list(string); default = [] }
variable "iam_inline_policy" { type = string; default = "" }
```

**`outputs.tf`**
```hcl
output "s3_bucket_arn" { value = module.s3.bucket_arn }
output "s3_bucket_name" { value = module.s3.bucket_name }

output "rds_endpoint" { value = module.rds.endpoint }
output "rds_hosted_zone" { value = module.rds.hosted_zone }
output "rds_secret_arn" { value = module.rds.secret_arn; sensitive = true }

output "iam_role_arn" { value = module.iam_role.role_arn }
output "iam_role_name" { value = module.iam_role.role_name }
```

---

### 🧩 Submodules

#### `modules/s3/main.tf`
```hcl
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = var.common_tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = ""
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn

  rule {
    status = "Enabled"
    filter {}
    destination {
      bucket        = var.destination_bucket_arn
      storage_class = "STANDARD"
    }
  }
}
```
*(`modules/s3/variables.tf` & `outputs.tf` contain standard `bucket_name`, `environment`, `common_tags`, `enable_replication`, `replication_role_arn`, `destination_bucket_arn`, and outputs `bucket_arn`, `bucket_name`)*

#### `modules/rds/main.tf`
```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.environment}-${var.identifier}-subnet-group"
  subnet_ids = var.vpc_subnet_ids
  tags       = var.common_tags
}

resource "aws_db_instance" "this" {
  identifier = var.identifier
  engine     = "postgres"
  engine_version = "15.4"
  instance_class = var.instance_class
  db_name        = var.db_name
  username       = var.master_username

  # Native secret management: creates AWS Secrets Manager secret encrypted at rest
  manage_master_user_password = true

  skip_final_snapshot = true
  deletion_protection = var.deletion_protection
  multi_az            = var.multi_az
  storage_encrypted   = var.storage_encrypted
  backup_retention_period = var.backup_retention_period
  publicly_accessible   = false
  vpc_security_group_ids = var.vpc_security_group_ids
  db_subnet_group_name  = aws_db_subnet_group.this.name
  tags                  = var.common_tags
}
```
*(`modules/rds/variables.tf` & `outputs.tf` contain env, identifier, instance_class, multi_az, storage_encrypted, deletion_protection, backup_retention_period, db_name, master_username, vpc_subnet_ids, vpc_security_group_ids, common_tags. Outputs: `endpoint`, `hosted_zone`, `secret_arn`)*

#### `modules/iam_role/main.tf`
```hcl
resource "aws_iam_role" "this" {
  name               = var.role_name
  assume_role_policy = var.assume_role_policy
  tags               = var.common_tags
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.policy_arns)
  role       = aws_iam_role.this.name
  policy_arn = each.value
}

resource "aws_iam_role_policy" "inline" {
  count  = var.inline_policy != "" ? 1 : 0
  name   = "${var.role_name}-inline-policy"
  role   = aws_iam_role.this.name
  policy = var.inline_policy
}
```
